// Build the Anthropic request for one negative item.
const it = $input.first().json;
const system = [
  'You are an FCRA compliance analyst for a licensed credit-repair',
  'service. Given one negative credit item, identify whether there is',
  'a GOOD-FAITH, factual basis to dispute it under the Fair Credit',
  'Reporting Act. Never invent inaccuracies. If the item appears',
  'accurate and verifiable, say so and recommend do_not_dispute.',
  'Return ONLY JSON.'
].join(' ');
const user = [
  'Negative item:', JSON.stringify(it, null, 2),
  '',
  'Return JSON: {"dispute_basis": one of',
  '["inaccurate","incomplete","unverifiable","obsolete",',
  '"not_mine","identity_theft","none"],',
  '"fcra_sections": [strings like "1681i","1681e(b)","1681s-2"],',
  '"rationale": string, "confidence": 0-1,',
  '"recommendation": "dispute" or "do_not_dispute"}'
].join('\n');
return [{ json: { ...it, anthropic_request: {
  model: 'claude-sonnet-4-6', max_tokens: 1024,
  system, messages: [{ role: 'user', content: user }] } } }];

// Extract the JSON verdict from Claude's response.
const resp = $input.first().json;
const text = (resp.content && resp.content[0] && resp.content[0].text) || '{}';
let verdict;
try { verdict = JSON.parse(text.match(/\{[\s\S]*\}/)[0]); }
catch (e) { verdict = { dispute_basis: 'none', confidence: 0,
  recommendation: 'do_not_dispute', rationale: 'parse_error' }; }
const it = $('Build Analysis Prompt').first().json;
return [{ json: { item_id: it.item_id, case_id: it.case_id,
  bureau: it.bureau, ...verdict,
  analysis_status: verdict.recommendation === 'dispute'
    ? 'disputable' : 'do_not_dispute' } }];

// After the loop: summarize disputable items grouped by bureau.
const all = $('DB: Save Item Analysis').all().map(i => i.json);
const disputable = all.filter(i => i.analysis_status === 'disputable');
const byBureau = {};
for (const it of disputable) {
  (byBureau[it.bureau] = byBureau[it.bureau] || []).push(it);
}
return [{ json: {
  case_id: all.length ? all[0].case_id : null,
  total_items: all.length,
  disputable_count: disputable.length,
  do_not_dispute_count: all.length - disputable.length,
  bureaus: Object.keys(byBureau),
  strategy_by_bureau: byBureau,
  stage: 'analyzed' } }];
